# Decision-readiness table (landing page): one row per operator requirement, the gate that
# blocks it, and the number that would clear it. Grounded in requirements/data/requirements.json
# and the documented demotion thresholds (ledger/data/demotion-rules.json, rule D4). Where a
# requirement is MET the gate is cleared; where no number can clear it (statistical or source
# impossibility) the cell says so rather than inventing a value.
READINESS_GATE={
 'RQ-05':('G5/G6 out-of-sample test; only n=15 settled','≥80 singles games in a validated out-of-sample window (D4)'),
 'RQ-06':('No strategy passes all applicable gates','≥1 strategy with G1–G8 PASS + an operator reward decision'),
 'RQ-07':('G7 joint-event validation; no player-level event-aligned dataset','a player-game-threshold-timestamp dataset (≥100 prop player-games, D4)'),
 'RQ-09':('Official-only inputs; leg-level dependence not published','officially sourced leg-level pairs, each with n (none published)'),
 'RQ-10':('Statistical impossibility in a finite sample','— (re-scoped to a conservative bound; cannot be cleared)'),
 'RQ-12':('No official pregame starter source (depth-chart URL 404)','— (postgame game books only; no pregame official source)'),
}
def readiness_table():
 rows=[]
 for r in req:
  if r['status']=='MET': gate,num='— (cleared)','— (met)'
  else: gate,num=READINESS_GATE.get(r['id'],('—','—'))
  badge=('<span class="badge good">MET</span>' if r['status']=='MET' else '<span class="badge warn">'+e(r['status'])+'</span>')
  short=r['requirement'][:96]+('…' if len(r['requirement'])>96 else '')
  rows.append([r['id'],short,badge,gate,num,a(r['source_url'])])
 return sec('Decision readiness · one row per requirement')+table(['ID','Requirement','Status','Blocking gate','Number that would clear it','Official reference'],rows,'Decision readiness')+note('A gate that is not cleared blocks the requirement, not the deploy. "NOT POSSIBLE" rows are blocked by the absence of an official source or by a statistical limit, not by missing effort; no value is inferred to clear them.')
